<?php $currency_symbol=$this->customlib->getSchoolCurrencyFormat(); $this->load->view('admin/feeworkspace/_header'); ?>
<div class="fw-card"><div class="fw-card-body"><div class="row"><div class="col-sm-8"><a href="<?php echo site_url('admin/feeworkspace/collect'); ?>" class="text-muted"><i class="fa fa-arrow-left"></i> Find another student</a><h3 style="margin:8px 0 3px"><?php echo html_escape(trim($student['firstname'].' '.$student['middlename'].' '.$student['lastname'])); ?></h3><span class="fw-pill"><?php echo html_escape($student['admission_no']); ?></span> <span class="fw-pill"><?php echo html_escape($student['class'].' / '.$student['section']); ?></span></div><div class="col-sm-4 text-right"><small>Guardian</small><br><strong><?php echo html_escape($student['guardian_name']); ?></strong><br><?php echo html_escape($student['guardian_phone']); ?></div></div></div></div>
<?php
$total=0;$paid_total=0;$discount_total=0;$balance_total=0;$rows=array();
foreach($student_due_fee as $group){ foreach($group->fees as $fee){
    $paid=0;$discount=0;$fine_paid=0;$deposits=array();
    if(!empty($fee->amount_detail)){ $decoded=json_decode($fee->amount_detail); if(is_array($decoded)||is_object($decoded)){foreach($decoded as $d){$paid+=(float)$d->amount;$discount+=(float)$d->amount_discount;$fine_paid+=(float)$d->amount_fine;$deposits[]=$d;}} }
    $balance=max(0,(float)$fee->amount-$paid-$discount);$total+=(float)$fee->amount;$paid_total+=$paid;$discount_total+=$discount;$balance_total+=$balance;
    $rows[]=array('group'=>$group,'fee'=>$fee,'paid'=>$paid,'discount'=>$discount,'fine_paid'=>$fine_paid,'balance'=>$balance,'deposits'=>$deposits);
}}
?>
<div class="row"><div class="col-sm-3"><div class="small-box bg-aqua"><div class="inner"><h3><?php echo $currency_symbol.number_format($total,2); ?></h3><p>Total assigned</p></div></div></div><div class="col-sm-3"><div class="small-box bg-green"><div class="inner"><h3><?php echo $currency_symbol.number_format($paid_total,2); ?></h3><p>Paid</p></div></div></div><div class="col-sm-3"><div class="small-box bg-yellow"><div class="inner"><h3><?php echo $currency_symbol.number_format($discount_total,2); ?></h3><p>Discount</p></div></div></div><div class="col-sm-3"><div class="small-box bg-red"><div class="inner"><h3><?php echo $currency_symbol.number_format($balance_total,2); ?></h3><p>Balance</p></div></div></div></div>
<div class="fw-card"><div class="fw-card-head"><h3>Fee account</h3></div><div class="fw-card-body table-responsive"><table class="table table-hover fw-table"><thead><tr><th>Fee</th><th>Due date</th><th>Status</th><th class="text-right">Amount</th><th class="text-right">Paid</th><th class="text-right">Discount</th><th class="text-right">Balance</th><th></th></tr></thead><tbody>
<?php foreach($rows as $r){$f=$r['fee'];$g=$r['group'];$status=$r['balance']<=0?'Paid':($r['paid']>0||$r['discount']>0?'Partial':'Unpaid'); ?>
<tr><td><strong><?php echo html_escape($f->type); ?></strong><br><small><?php echo html_escape($f->name.' · '.$f->code); ?></small></td><td><?php echo ($f->due_date && $f->due_date!=='0000-00-00')?html_escape($f->due_date):'—'; ?></td><td><span class="label label-<?php echo $status==='Paid'?'success':($status==='Partial'?'warning':'danger'); ?>"><?php echo $status; ?></span></td><td class="text-right"><?php echo number_format($f->amount,2); ?></td><td class="text-right"><?php echo number_format($r['paid'],2); ?></td><td class="text-right"><?php echo number_format($r['discount'],2); ?></td><td class="text-right"><strong><?php echo number_format($r['balance'],2); ?></strong></td><td class="text-right"><?php if($r['balance']>0){ ?><button class="btn btn-success btn-sm fw-collect" data-toggle="modal" data-target="#fw-pay" data-master="<?php echo (int)$g->id; ?>" data-feetype="<?php echo (int)$f->fee_groups_feetype_id; ?>" data-balance="<?php echo $r['balance']; ?>" data-title="<?php echo html_escape($f->type); ?>">Pay</button><?php } ?></td></tr>
<?php foreach($r['deposits'] as $d){ ?><tr class="text-muted"><td colspan="2" class="text-right"><i class="fa fa-level-up fa-rotate-90"></i> Receipt</td><td><?php echo html_escape($d->payment_mode); ?></td><td><?php echo html_escape($d->date); ?></td><td class="text-right"><?php echo number_format($d->amount,2); ?></td><td class="text-right"><?php echo number_format($d->amount_discount,2); ?></td><td colspan="2"></td></tr><?php } ?>
<?php } if(empty($rows)){ ?><tr><td colspan="8" class="fw-empty">No generated fee is assigned to this student.</td></tr><?php } ?>
</tbody></table></div></div>
<div class="fw-note"><i class="fa fa-university"></i> Select the receiving cash/bank account. The same existing operation records the receipt and prepares its Chart of Accounts voucher.</div>

<div class="modal fade" id="fw-pay"><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><button class="close" data-dismiss="modal">&times;</button><h4 class="modal-title">Collect payment — <span id="fw-fee-title"></span></h4></div><div class="modal-body">
<input type="hidden" id="fw-master"><input type="hidden" id="fw-feetype"><div class="row"><div class="col-sm-6 form-group"><label>Amount *</label><input class="form-control" type="number" min="0.01" step="0.01" id="fw-amount"></div><div class="col-sm-3 form-group"><label>Discount</label><input class="form-control" type="number" min="0" step="0.01" value="0" id="fw-discount"></div><div class="col-sm-3 form-group"><label>Fine</label><input class="form-control" type="number" min="0" step="0.01" value="0" id="fw-fine"></div></div>
<div class="row"><div class="col-sm-6 form-group"><label>Payment mode *</label><select class="form-control" id="fw-mode"><option>Cash</option><option>JazzCash</option><option value="bank_transfer">Bank Transfer</option><option value="card">Card</option><option value="upi">UPI</option><option>DD</option></select></div><div class="col-sm-6 form-group"><label>Receiving account *</label><select class="form-control" id="fw-bank"><option value="">Select account</option><?php foreach($bank_accounts as $a){ ?><option value="<?php echo (int)$a['id']; ?>"><?php echo html_escape($a['account_name'].' ('.$a['account_number'].')'); ?></option><?php } ?></select></div></div>
<div class="form-group"><label>Note</label><textarea class="form-control" id="fw-description" rows="2"></textarea></div><div class="alert alert-danger" id="fw-pay-error" style="display:none"></div>
</div><div class="modal-footer"><button class="btn btn-default" data-dismiss="modal">Cancel</button><button class="btn btn-success" id="fw-save-pay"><i class="fa fa-check"></i> Collect & Save</button></div></div></div></div>
<script>
(function($){var selectedBalance=0;$('.fw-collect').on('click',function(){var b=$(this);selectedBalance=parseFloat(b.data('balance'));$('#fw-master').val(b.data('master'));$('#fw-feetype').val(b.data('feetype'));$('#fw-amount').val(selectedBalance.toFixed(2));$('#fw-fee-title').text(b.data('title'));$('#fw-pay-error').hide();});
$('#fw-save-pay').on('click',function(){var btn=$(this),amount=parseFloat($('#fw-amount').val()),discount=parseFloat($('#fw-discount').val()||0);if(!amount||amount<=0||amount+discount>selectedBalance+.001){return fail('Amount plus discount cannot exceed the outstanding balance.');}if(!$('#fw-bank').val())return fail('Select the receiving cash or bank account.');if(btn.data('busy'))return;btn.data('busy',1).prop('disabled',true).html('<i class="fa fa-spinner fa-spin"></i> Saving payment...');$.ajax({url:'<?php echo site_url('studentfee/addstudentfee'); ?>',type:'POST',dataType:'json',data:{action:'collect',student_session_id:<?php echo (int)$student['student_session_id']; ?>,date:<?php echo json_encode(date($this->customlib->getSchoolDateFormat())); ?>,amount:amount,amount_discount:discount,amount_fine:$('#fw-fine').val()||0,description:$('#fw-description').val(),student_fees_master_id:$('#fw-master').val(),fee_groups_feetype_id:$('#fw-feetype').val(),payment_mode:$('#fw-mode').val(),guardian_phone:<?php echo json_encode($student['guardian_phone']); ?>,guardian_email:<?php echo json_encode($student['guardian_email']); ?>,parent_app_key:<?php echo json_encode($student['parent_app_key']); ?>,student_fees_discount_id:'',bank_account_id:$('#fw-bank').val()}}).done(function(r){if(r.status==='success'){location.reload();return;}var msg='Payment was not saved.';if(r.error)msg=Object.keys(r.error).map(function(k){return r.error[k]}).join(' ');fail(msg);}).fail(function(){fail('The payment could not be saved. No success was reported.');}).always(function(){btn.data('busy',0).prop('disabled',false).html('<i class="fa fa-check"></i> Collect & Save');});});function fail(m){$('#fw-pay-error').text($('<div>').html(m).text()).show();return false;}})(jQuery);
</script>
